with c as (select id from public.academy_courses where id='meteorology-forecasting-foundations'),
ch as (insert into public.academy_chapters(course_id,title,description,sort_order,published) select id,'الكهرباء الجوية والبرق ورصد العواصف','المجال الكهربائي الجوي وفصل الشحنات والتفريغ البرقي وشبكات الكشف والتكهرب المرتبط بالهباء والعواصف وتحليل المنتجات التشغيلية.',62,false from c on conflict(course_id,title) do update set description=excluded.description returning id),
u1 as (insert into public.academy_units(chapter_id,title,sort_order,published) select id,'الكهرباء الجوية وتكهرب السحب',1,false from ch on conflict(chapter_id,title) do update set sort_order=excluded.sort_order returning id),
u2 as (insert into public.academy_units(chapter_id,title,sort_order,published) select id,'شبكات كشف البرق والتحليل التشغيلي',2,false from ch on conflict(chapter_id,title) do update set sort_order=excluded.sort_order returning id),
d(slug,title,summary,content,ord,mins,objectives,unit_title) as (values
('atmospheric-electric-field','المجال الكهربائي للغلاف الجوي','الجهد والتدرج الكهربائي قرب السطح','{"blocks":[{"type":"heading","text":"المفهوم العلمي"},{"type":"text","text":"يتغير المجال الكهربائي الجوي مع الشحنات السحابية والهباء والموصلية والطقس، وتقاس شدته واتجاهه بأجهزة متخصصة. يجب فصل المجال في الطقس الهادئ عن الاضطرابات المرتبطة بالعواصف."},{"type":"heading","text":"الأساس الفيزيائي"},{"type":"text","text":"تنتج الظواهر الكهربائية الجوية من حركة الشحنات وفصلها وانتقالها ضمن وسط غازي متغير الموصلية. ويتطلب تفسيرها الجمع بين القياس الكهربائي والظروف الميكروفيزيائية والديناميكية والبيئية، مع التمييز بين الإشارة المقاسة والاستنتاج الفيزيائي."},{"type":"heading","text":"البيانات والأجهزة"},{"type":"list","items":["المجال الكهربائي والجهد والتيار أو الموصلية بحسب الجهاز.","إشارات المستشعرات الكهرومغناطيسية أو البصرية وتوقيتها.","بيانات الرادار والأقمار الصناعية والطقس السطحي.","موقع المحطات وهندستها ومعايرتها وحالة الاتصال.","سجلات الأحداث الخام وبيانات ضبط الجودة."]},{"type":"heading","text":"منهجية التحليل"},{"type":"list","items":["حدد الظاهرة ونوع الإشارة التي يقيسها الجهاز مباشرة.","تحقق من التوقيت والمعايرة وحدود الكشف.","اربط الإشارة بالبنية السحابية والبيئة الجوية.","ادمج مصادر الرصد مع توحيد الإسقاط والزمن.","اعرض عدم اليقين والتغطية ومعدل الأحداث غير المكتشفة."]},{"type":"heading","text":"مثال تطبيقي"},{"type":"example","title":"المجال الكهربائي للغلاف الجوي","text":"حدد المتغيرات التي ينبغي تسجيلها مع قراءة المجال الكهربائي. استخدم حالة افتراضية تعليمية، وبيّن ما يمكن استنتاجه وما يحتاج إلى قياسات إضافية."},{"type":"heading","text":"المهمة العملية"},{"type":"text","text":"حدد المتغيرات التي ينبغي تسجيلها مع قراءة المجال الكهربائي."},{"type":"heading","text":"أخطاء شائعة"},{"type":"list","items":["اعتبار كل إشارة كهربائية حدث برق مؤكداً.","إهمال كفاءة الكشف وتغيرها مع الزمن.","الخلط بين كثافة الأحداث ومستوى الخطر المحلي.","دمج مصادر غير متزامنة دون توثيق الفروق الزمنية.","إسناد اتجاه مناخي قبل فحص تجانس شبكة الرصد."]},{"type":"callout","text":"تفسير البرق والكهرباء الجوية يتطلب شبكة رصد معايرة وسياقاً جوياً متكاملاً، لا مجرد عرض نقاط على الخريطة."},{"type":"heading","text":"الخلاصة"},{"type":"text","text":"يوفر الرصد الكهربائي بعداً إضافياً لفهم العواصف والهباء والغلاف الجوي. وتنبع القيمة التشغيلية من تكامل المستشعرات وضبط الجودة والتفسير متعدد المصادر."}]}'::jsonb,8560,55,'["شرح الآلية الكهربائية الجوية أو مبدأ الرصد المرتبط بالموضوع","تحليل بيانات المستشعرات وربطها بالسياق الجوي","تقييم جودة الشبكة ومصادر عدم اليقين في المنتجات"]'::jsonb,'الكهرباء الجوية وتكهرب السحب'),
('global-electric-circuit','الدائرة الكهربائية العالمية','العواصف والموصلية والتيار الرأسي','{"blocks":[{"type":"heading","text":"المفهوم العلمي"},{"type":"text","text":"تصف الدائرة الكهربائية العالمية تبادل التيار بين سطح الأرض والغلاف الجوي العلوي، مع مساهمة العواصف الرعدية في المحافظة على فرق الجهد. تتأثر القياسات بالموصلية الجوية والهباء والظروف المحلية."},{"type":"heading","text":"الأساس الفيزيائي"},{"type":"text","text":"تنتج الظواهر الكهربائية الجوية من حركة الشحنات وفصلها وانتقالها ضمن وسط غازي متغير الموصلية. ويتطلب تفسيرها الجمع بين القياس الكهربائي والظروف الميكروفيزيائية والديناميكية والبيئية، مع التمييز بين الإشارة المقاسة والاستنتاج الفيزيائي."},{"type":"heading","text":"البيانات والأجهزة"},{"type":"list","items":["المجال الكهربائي والجهد والتيار أو الموصلية بحسب الجهاز.","إشارات المستشعرات الكهرومغناطيسية أو البصرية وتوقيتها.","بيانات الرادار والأقمار الصناعية والطقس السطحي.","موقع المحطات وهندستها ومعايرتها وحالة الاتصال.","سجلات الأحداث الخام وبيانات ضبط الجودة."]},{"type":"heading","text":"منهجية التحليل"},{"type":"list","items":["حدد الظاهرة ونوع الإشارة التي يقيسها الجهاز مباشرة.","تحقق من التوقيت والمعايرة وحدود الكشف.","اربط الإشارة بالبنية السحابية والبيئة الجوية.","ادمج مصادر الرصد مع توحيد الإسقاط والزمن.","اعرض عدم اليقين والتغطية ومعدل الأحداث غير المكتشفة."]},{"type":"heading","text":"مثال تطبيقي"},{"type":"example","title":"الدائرة الكهربائية العالمية","text":"اشرح بصورة مفاهيمية دور العواصف في الدائرة الكهربائية العالمية. استخدم حالة افتراضية تعليمية، وبيّن ما يمكن استنتاجه وما يحتاج إلى قياسات إضافية."},{"type":"heading","text":"المهمة العملية"},{"type":"text","text":"اشرح بصورة مفاهيمية دور العواصف في الدائرة الكهربائية العالمية."},{"type":"heading","text":"أخطاء شائعة"},{"type":"list","items":["اعتبار كل إشارة كهربائية حدث برق مؤكداً.","إهمال كفاءة الكشف وتغيرها مع الزمن.","الخلط بين كثافة الأحداث ومستوى الخطر المحلي.","دمج مصادر غير متزامنة دون توثيق الفروق الزمنية.","إسناد اتجاه مناخي قبل فحص تجانس شبكة الرصد."]},{"type":"callout","text":"تفسير البرق والكهرباء الجوية يتطلب شبكة رصد معايرة وسياقاً جوياً متكاملاً، لا مجرد عرض نقاط على الخريطة."},{"type":"heading","text":"الخلاصة"},{"type":"text","text":"يوفر الرصد الكهربائي بعداً إضافياً لفهم العواصف والهباء والغلاف الجوي. وتنبع القيمة التشغيلية من تكامل المستشعرات وضبط الجودة والتفسير متعدد المصادر."}]}'::jsonb,8570,55,'["شرح الآلية الكهربائية الجوية أو مبدأ الرصد المرتبط بالموضوع","تحليل بيانات المستشعرات وربطها بالسياق الجوي","تقييم جودة الشبكة ومصادر عدم اليقين في المنتجات"]'::jsonb,'الكهرباء الجوية وتكهرب السحب'),
('fair-weather-electricity','الكهرباء الجوية في الطقس الصحو','التدرج الجهدي والموصلية','{"blocks":[{"type":"heading","text":"المفهوم العلمي"},{"type":"text","text":"يمثل الطقس الصحو مرجعاً لدراسة المجال الكهربائي الجوي بعيداً عن التأثيرات المحلية للعواصف. يتأثر التدرج الجهدي بالهباء والتلوث والارتفاع والتضاريس والمصادر القريبة."},{"type":"heading","text":"الأساس الفيزيائي"},{"type":"text","text":"تنتج الظواهر الكهربائية الجوية من حركة الشحنات وفصلها وانتقالها ضمن وسط غازي متغير الموصلية. ويتطلب تفسيرها الجمع بين القياس الكهربائي والظروف الميكروفيزيائية والديناميكية والبيئية، مع التمييز بين الإشارة المقاسة والاستنتاج الفيزيائي."},{"type":"heading","text":"البيانات والأجهزة"},{"type":"list","items":["المجال الكهربائي والجهد والتيار أو الموصلية بحسب الجهاز.","إشارات المستشعرات الكهرومغناطيسية أو البصرية وتوقيتها.","بيانات الرادار والأقمار الصناعية والطقس السطحي.","موقع المحطات وهندستها ومعايرتها وحالة الاتصال.","سجلات الأحداث الخام وبيانات ضبط الجودة."]},{"type":"heading","text":"منهجية التحليل"},{"type":"list","items":["حدد الظاهرة ونوع الإشارة التي يقيسها الجهاز مباشرة.","تحقق من التوقيت والمعايرة وحدود الكشف.","اربط الإشارة بالبنية السحابية والبيئة الجوية.","ادمج مصادر الرصد مع توحيد الإسقاط والزمن.","اعرض عدم اليقين والتغطية ومعدل الأحداث غير المكتشفة."]},{"type":"heading","text":"مثال تطبيقي"},{"type":"example","title":"الكهرباء الجوية في الطقس الصحو","text":"قارن بين بيئة ريفية وأخرى حضرية في تفسير المجال الكهربائي الصحو. استخدم حالة افتراضية تعليمية، وبيّن ما يمكن استنتاجه وما يحتاج إلى قياسات إضافية."},{"type":"heading","text":"المهمة العملية"},{"type":"text","text":"قارن بين بيئة ريفية وأخرى حضرية في تفسير المجال الكهربائي الصحو."},{"type":"heading","text":"أخطاء شائعة"},{"type":"list","items":["اعتبار كل إشارة كهربائية حدث برق مؤكداً.","إهمال كفاءة الكشف وتغيرها مع الزمن.","الخلط بين كثافة الأحداث ومستوى الخطر المحلي.","دمج مصادر غير متزامنة دون توثيق الفروق الزمنية.","إسناد اتجاه مناخي قبل فحص تجانس شبكة الرصد."]},{"type":"callout","text":"تفسير البرق والكهرباء الجوية يتطلب شبكة رصد معايرة وسياقاً جوياً متكاملاً، لا مجرد عرض نقاط على الخريطة."},{"type":"heading","text":"الخلاصة"},{"type":"text","text":"يوفر الرصد الكهربائي بعداً إضافياً لفهم العواصف والهباء والغلاف الجوي. وتنبع القيمة التشغيلية من تكامل المستشعرات وضبط الجودة والتفسير متعدد المصادر."}]}'::jsonb,8580,55,'["شرح الآلية الكهربائية الجوية أو مبدأ الرصد المرتبط بالموضوع","تحليل بيانات المستشعرات وربطها بالسياق الجوي","تقييم جودة الشبكة ومصادر عدم اليقين في المنتجات"]'::jsonb,'الكهرباء الجوية وتكهرب السحب'),
('thunderstorm-charge-separation','فصل الشحنات داخل العواصف الرعدية','التصادمات والجليد والتيارات الرأسية','{"blocks":[{"type":"heading","text":"المفهوم العلمي"},{"type":"text","text":"تتوزع الشحنات الكهربائية في السحب الرعدية نتيجة تفاعلات بين البلورات الجليدية والحبيبات والقطرات فائقة التبريد ضمن تيارات صاعدة وهابطة. يختلف التوزيع باختلاف بنية العاصفة والحرارة والمحتوى المائي."},{"type":"heading","text":"الأساس الفيزيائي"},{"type":"text","text":"تنتج الظواهر الكهربائية الجوية من حركة الشحنات وفصلها وانتقالها ضمن وسط غازي متغير الموصلية. ويتطلب تفسيرها الجمع بين القياس الكهربائي والظروف الميكروفيزيائية والديناميكية والبيئية، مع التمييز بين الإشارة المقاسة والاستنتاج الفيزيائي."},{"type":"heading","text":"البيانات والأجهزة"},{"type":"list","items":["المجال الكهربائي والجهد والتيار أو الموصلية بحسب الجهاز.","إشارات المستشعرات الكهرومغناطيسية أو البصرية وتوقيتها.","بيانات الرادار والأقمار الصناعية والطقس السطحي.","موقع المحطات وهندستها ومعايرتها وحالة الاتصال.","سجلات الأحداث الخام وبيانات ضبط الجودة."]},{"type":"heading","text":"منهجية التحليل"},{"type":"list","items":["حدد الظاهرة ونوع الإشارة التي يقيسها الجهاز مباشرة.","تحقق من التوقيت والمعايرة وحدود الكشف.","اربط الإشارة بالبنية السحابية والبيئة الجوية.","ادمج مصادر الرصد مع توحيد الإسقاط والزمن.","اعرض عدم اليقين والتغطية ومعدل الأحداث غير المكتشفة."]},{"type":"heading","text":"مثال تطبيقي"},{"type":"example","title":"فصل الشحنات داخل العواصف الرعدية","text":"اربط بين الطور المائي والتصادمات وتطور البنية الكهربائية للسحابة. استخدم حالة افتراضية تعليمية، وبيّن ما يمكن استنتاجه وما يحتاج إلى قياسات إضافية."},{"type":"heading","text":"المهمة العملية"},{"type":"text","text":"اربط بين الطور المائي والتصادمات وتطور البنية الكهربائية للسحابة."},{"type":"heading","text":"أخطاء شائعة"},{"type":"list","items":["اعتبار كل إشارة كهربائية حدث برق مؤكداً.","إهمال كفاءة الكشف وتغيرها مع الزمن.","الخلط بين كثافة الأحداث ومستوى الخطر المحلي.","دمج مصادر غير متزامنة دون توثيق الفروق الزمنية.","إسناد اتجاه مناخي قبل فحص تجانس شبكة الرصد."]},{"type":"callout","text":"تفسير البرق والكهرباء الجوية يتطلب شبكة رصد معايرة وسياقاً جوياً متكاملاً، لا مجرد عرض نقاط على الخريطة."},{"type":"heading","text":"الخلاصة"},{"type":"text","text":"يوفر الرصد الكهربائي بعداً إضافياً لفهم العواصف والهباء والغلاف الجوي. وتنبع القيمة التشغيلية من تكامل المستشعرات وضبط الجودة والتفسير متعدد المصادر."}]}'::jsonb,8590,55,'["شرح الآلية الكهربائية الجوية أو مبدأ الرصد المرتبط بالموضوع","تحليل بيانات المستشعرات وربطها بالسياق الجوي","تقييم جودة الشبكة ومصادر عدم اليقين في المنتجات"]'::jsonb,'الكهرباء الجوية وتكهرب السحب'),
('cloud-electrification-microphysics','الميكروفيزياء والتكهرب السحابي','التفاعلات بين الجليد والماء الفائق التبريد','{"blocks":[{"type":"heading","text":"المفهوم العلمي"},{"type":"text","text":"تؤثر عمليات النمو والتجمد والتجمع والتصادم في انتقال الشحنة بين الجسيمات السحابية. لذلك يرتبط فهم الكهرباء السحابية بتحليل الأطوار المائية وتوزيع أحجام الجسيمات والتيارات الرأسية."},{"type":"heading","text":"الأساس الفيزيائي"},{"type":"text","text":"تنتج الظواهر الكهربائية الجوية من حركة الشحنات وفصلها وانتقالها ضمن وسط غازي متغير الموصلية. ويتطلب تفسيرها الجمع بين القياس الكهربائي والظروف الميكروفيزيائية والديناميكية والبيئية، مع التمييز بين الإشارة المقاسة والاستنتاج الفيزيائي."},{"type":"heading","text":"البيانات والأجهزة"},{"type":"list","items":["المجال الكهربائي والجهد والتيار أو الموصلية بحسب الجهاز.","إشارات المستشعرات الكهرومغناطيسية أو البصرية وتوقيتها.","بيانات الرادار والأقمار الصناعية والطقس السطحي.","موقع المحطات وهندستها ومعايرتها وحالة الاتصال.","سجلات الأحداث الخام وبيانات ضبط الجودة."]},{"type":"heading","text":"منهجية التحليل"},{"type":"list","items":["حدد الظاهرة ونوع الإشارة التي يقيسها الجهاز مباشرة.","تحقق من التوقيت والمعايرة وحدود الكشف.","اربط الإشارة بالبنية السحابية والبيئة الجوية.","ادمج مصادر الرصد مع توحيد الإسقاط والزمن.","اعرض عدم اليقين والتغطية ومعدل الأحداث غير المكتشفة."]},{"type":"heading","text":"مثال تطبيقي"},{"type":"example","title":"الميكروفيزياء والتكهرب السحابي","text":"فسر لماذا ترتبط شدة التكهرب ببيئة السحابة الميكروفيزيائية. استخدم حالة افتراضية تعليمية، وبيّن ما يمكن استنتاجه وما يحتاج إلى قياسات إضافية."},{"type":"heading","text":"المهمة العملية"},{"type":"text","text":"فسر لماذا ترتبط شدة التكهرب ببيئة السحابة الميكروفيزيائية."},{"type":"heading","text":"أخطاء شائعة"},{"type":"list","items":["اعتبار كل إشارة كهربائية حدث برق مؤكداً.","إهمال كفاءة الكشف وتغيرها مع الزمن.","الخلط بين كثافة الأحداث ومستوى الخطر المحلي.","دمج مصادر غير متزامنة دون توثيق الفروق الزمنية.","إسناد اتجاه مناخي قبل فحص تجانس شبكة الرصد."]},{"type":"callout","text":"تفسير البرق والكهرباء الجوية يتطلب شبكة رصد معايرة وسياقاً جوياً متكاملاً، لا مجرد عرض نقاط على الخريطة."},{"type":"heading","text":"الخلاصة"},{"type":"text","text":"يوفر الرصد الكهربائي بعداً إضافياً لفهم العواصف والهباء والغلاف الجوي. وتنبع القيمة التشغيلية من تكامل المستشعرات وضبط الجودة والتفسير متعدد المصادر."}]}'::jsonb,8600,55,'["شرح الآلية الكهربائية الجوية أو مبدأ الرصد المرتبط بالموضوع","تحليل بيانات المستشعرات وربطها بالسياق الجوي","تقييم جودة الشبكة ومصادر عدم اليقين في المنتجات"]'::jsonb,'الكهرباء الجوية وتكهرب السحب'),
('lightning-discharge-physics','فيزياء التفريغ البرقي','تطور القنوات والتأين','{"blocks":[{"type":"heading","text":"المفهوم العلمي"},{"type":"text","text":"يمثل البرق تفريغاً كهربائياً في الغلاف الجوي يحدث عندما تتطور ظروف التأين والانهيار الكهربائي. تدرس الفيزياء الرصدية خصائص الإشارة الضوئية والكهرومغناطيسية دون اختزال الظاهرة إلى قيمة واحدة."},{"type":"heading","text":"الأساس الفيزيائي"},{"type":"text","text":"تنتج الظواهر الكهربائية الجوية من حركة الشحنات وفصلها وانتقالها ضمن وسط غازي متغير الموصلية. ويتطلب تفسيرها الجمع بين القياس الكهربائي والظروف الميكروفيزيائية والديناميكية والبيئية، مع التمييز بين الإشارة المقاسة والاستنتاج الفيزيائي."},{"type":"heading","text":"البيانات والأجهزة"},{"type":"list","items":["المجال الكهربائي والجهد والتيار أو الموصلية بحسب الجهاز.","إشارات المستشعرات الكهرومغناطيسية أو البصرية وتوقيتها.","بيانات الرادار والأقمار الصناعية والطقس السطحي.","موقع المحطات وهندستها ومعايرتها وحالة الاتصال.","سجلات الأحداث الخام وبيانات ضبط الجودة."]},{"type":"heading","text":"منهجية التحليل"},{"type":"list","items":["حدد الظاهرة ونوع الإشارة التي يقيسها الجهاز مباشرة.","تحقق من التوقيت والمعايرة وحدود الكشف.","اربط الإشارة بالبنية السحابية والبيئة الجوية.","ادمج مصادر الرصد مع توحيد الإسقاط والزمن.","اعرض عدم اليقين والتغطية ومعدل الأحداث غير المكتشفة."]},{"type":"heading","text":"مثال تطبيقي"},{"type":"example","title":"فيزياء التفريغ البرقي","text":"حدد الخصائص الرصدية التي تميز تفريغاً برقياً عن ضوضاء القياس. استخدم حالة افتراضية تعليمية، وبيّن ما يمكن استنتاجه وما يحتاج إلى قياسات إضافية."},{"type":"heading","text":"المهمة العملية"},{"type":"text","text":"حدد الخصائص الرصدية التي تميز تفريغاً برقياً عن ضوضاء القياس."},{"type":"heading","text":"أخطاء شائعة"},{"type":"list","items":["اعتبار كل إشارة كهربائية حدث برق مؤكداً.","إهمال كفاءة الكشف وتغيرها مع الزمن.","الخلط بين كثافة الأحداث ومستوى الخطر المحلي.","دمج مصادر غير متزامنة دون توثيق الفروق الزمنية.","إسناد اتجاه مناخي قبل فحص تجانس شبكة الرصد."]},{"type":"callout","text":"تفسير البرق والكهرباء الجوية يتطلب شبكة رصد معايرة وسياقاً جوياً متكاملاً، لا مجرد عرض نقاط على الخريطة."},{"type":"heading","text":"الخلاصة"},{"type":"text","text":"يوفر الرصد الكهربائي بعداً إضافياً لفهم العواصف والهباء والغلاف الجوي. وتنبع القيمة التشغيلية من تكامل المستشعرات وضبط الجودة والتفسير متعدد المصادر."}]}'::jsonb,8610,55,'["شرح الآلية الكهربائية الجوية أو مبدأ الرصد المرتبط بالموضوع","تحليل بيانات المستشعرات وربطها بالسياق الجوي","تقييم جودة الشبكة ومصادر عدم اليقين في المنتجات"]'::jsonb,'الكهرباء الجوية وتكهرب السحب'),
('intracloud-cloud-ground-lightning','أنواع البرق داخل السحب وبين السحب والأرض','تصنيف مسارات التفريغ','{"blocks":[{"type":"heading","text":"المفهوم العلمي"},{"type":"text","text":"تصنف التفريغات بحسب مسارها ومواقع الشحنات، وتشمل التفريغ داخل السحابة وبين السحب والتفريغ السحابي الأرضي. تختلف قابلية الرصد والتصنيف حسب شبكة المستشعرات وهندستها."},{"type":"heading","text":"الأساس الفيزيائي"},{"type":"text","text":"تنتج الظواهر الكهربائية الجوية من حركة الشحنات وفصلها وانتقالها ضمن وسط غازي متغير الموصلية. ويتطلب تفسيرها الجمع بين القياس الكهربائي والظروف الميكروفيزيائية والديناميكية والبيئية، مع التمييز بين الإشارة المقاسة والاستنتاج الفيزيائي."},{"type":"heading","text":"البيانات والأجهزة"},{"type":"list","items":["المجال الكهربائي والجهد والتيار أو الموصلية بحسب الجهاز.","إشارات المستشعرات الكهرومغناطيسية أو البصرية وتوقيتها.","بيانات الرادار والأقمار الصناعية والطقس السطحي.","موقع المحطات وهندستها ومعايرتها وحالة الاتصال.","سجلات الأحداث الخام وبيانات ضبط الجودة."]},{"type":"heading","text":"منهجية التحليل"},{"type":"list","items":["حدد الظاهرة ونوع الإشارة التي يقيسها الجهاز مباشرة.","تحقق من التوقيت والمعايرة وحدود الكشف.","اربط الإشارة بالبنية السحابية والبيئة الجوية.","ادمج مصادر الرصد مع توحيد الإسقاط والزمن.","اعرض عدم اليقين والتغطية ومعدل الأحداث غير المكتشفة."]},{"type":"heading","text":"مثال تطبيقي"},{"type":"example","title":"أنواع البرق داخل السحب وبين السحب والأرض","text":"قارن ما يمكن أن تكشفه شبكة أرضية وشبكة بصرية عن أنواع البرق. استخدم حالة افتراضية تعليمية، وبيّن ما يمكن استنتاجه وما يحتاج إلى قياسات إضافية."},{"type":"heading","text":"المهمة العملية"},{"type":"text","text":"قارن ما يمكن أن تكشفه شبكة أرضية وشبكة بصرية عن أنواع البرق."},{"type":"heading","text":"أخطاء شائعة"},{"type":"list","items":["اعتبار كل إشارة كهربائية حدث برق مؤكداً.","إهمال كفاءة الكشف وتغيرها مع الزمن.","الخلط بين كثافة الأحداث ومستوى الخطر المحلي.","دمج مصادر غير متزامنة دون توثيق الفروق الزمنية.","إسناد اتجاه مناخي قبل فحص تجانس شبكة الرصد."]},{"type":"callout","text":"تفسير البرق والكهرباء الجوية يتطلب شبكة رصد معايرة وسياقاً جوياً متكاملاً، لا مجرد عرض نقاط على الخريطة."},{"type":"heading","text":"الخلاصة"},{"type":"text","text":"يوفر الرصد الكهربائي بعداً إضافياً لفهم العواصف والهباء والغلاف الجوي. وتنبع القيمة التشغيلية من تكامل المستشعرات وضبط الجودة والتفسير متعدد المصادر."}]}'::jsonb,8620,55,'["شرح الآلية الكهربائية الجوية أو مبدأ الرصد المرتبط بالموضوع","تحليل بيانات المستشعرات وربطها بالسياق الجوي","تقييم جودة الشبكة ومصادر عدم اليقين في المنتجات"]'::jsonb,'الكهرباء الجوية وتكهرب السحب'),
('lightning-detection-networks','شبكات كشف البرق','المستشعرات الكهرومغناطيسية والتحديد المكاني','{"blocks":[{"type":"heading","text":"المفهوم العلمي"},{"type":"text","text":"تستخدم شبكات كشف البرق مستشعرات متزامنة لالتقاط الإشارات وتقدير زمن الوصول والاتجاه أو الموقع. تعتمد الدقة على التزامن والهندسة وكثافة المحطات وخوارزميات المعالجة."},{"type":"heading","text":"الأساس الفيزيائي"},{"type":"text","text":"تنتج الظواهر الكهربائية الجوية من حركة الشحنات وفصلها وانتقالها ضمن وسط غازي متغير الموصلية. ويتطلب تفسيرها الجمع بين القياس الكهربائي والظروف الميكروفيزيائية والديناميكية والبيئية، مع التمييز بين الإشارة المقاسة والاستنتاج الفيزيائي."},{"type":"heading","text":"البيانات والأجهزة"},{"type":"list","items":["المجال الكهربائي والجهد والتيار أو الموصلية بحسب الجهاز.","إشارات المستشعرات الكهرومغناطيسية أو البصرية وتوقيتها.","بيانات الرادار والأقمار الصناعية والطقس السطحي.","موقع المحطات وهندستها ومعايرتها وحالة الاتصال.","سجلات الأحداث الخام وبيانات ضبط الجودة."]},{"type":"heading","text":"منهجية التحليل"},{"type":"list","items":["حدد الظاهرة ونوع الإشارة التي يقيسها الجهاز مباشرة.","تحقق من التوقيت والمعايرة وحدود الكشف.","اربط الإشارة بالبنية السحابية والبيئة الجوية.","ادمج مصادر الرصد مع توحيد الإسقاط والزمن.","اعرض عدم اليقين والتغطية ومعدل الأحداث غير المكتشفة."]},{"type":"heading","text":"مثال تطبيقي"},{"type":"example","title":"شبكات كشف البرق","text":"اشرح كيف يؤثر توزيع المستشعرات في جودة تحديد موقع التفريغ. استخدم حالة افتراضية تعليمية، وبيّن ما يمكن استنتاجه وما يحتاج إلى قياسات إضافية."},{"type":"heading","text":"المهمة العملية"},{"type":"text","text":"اشرح كيف يؤثر توزيع المستشعرات في جودة تحديد موقع التفريغ."},{"type":"heading","text":"أخطاء شائعة"},{"type":"list","items":["اعتبار كل إشارة كهربائية حدث برق مؤكداً.","إهمال كفاءة الكشف وتغيرها مع الزمن.","الخلط بين كثافة الأحداث ومستوى الخطر المحلي.","دمج مصادر غير متزامنة دون توثيق الفروق الزمنية.","إسناد اتجاه مناخي قبل فحص تجانس شبكة الرصد."]},{"type":"callout","text":"تفسير البرق والكهرباء الجوية يتطلب شبكة رصد معايرة وسياقاً جوياً متكاملاً، لا مجرد عرض نقاط على الخريطة."},{"type":"heading","text":"الخلاصة"},{"type":"text","text":"يوفر الرصد الكهربائي بعداً إضافياً لفهم العواصف والهباء والغلاف الجوي. وتنبع القيمة التشغيلية من تكامل المستشعرات وضبط الجودة والتفسير متعدد المصادر."}]}'::jsonb,8630,55,'["شرح الآلية الكهربائية الجوية أو مبدأ الرصد المرتبط بالموضوع","تحليل بيانات المستشعرات وربطها بالسياق الجوي","تقييم جودة الشبكة ومصادر عدم اليقين في المنتجات"]'::jsonb,'الكهرباء الجوية وتكهرب السحب'),
('lightning-location-uncertainty','عدم اليقين في تحديد مواقع البرق','الهندسة والتزامن وانتشار الإشارة','{"blocks":[{"type":"heading","text":"المفهوم العلمي"},{"type":"text","text":"تتأثر دقة موقع البرق بأخطاء التوقيت ومزامنة الساعات وتفاوت حساسية المستشعرات وانتشار الإشارة. ينبغي عرض الموقع مع تقدير عدم اليقين وعدم التعامل مع كل نقطة على أنها دقيقة تماماً."},{"type":"heading","text":"الأساس الفيزيائي"},{"type":"text","text":"تنتج الظواهر الكهربائية الجوية من حركة الشحنات وفصلها وانتقالها ضمن وسط غازي متغير الموصلية. ويتطلب تفسيرها الجمع بين القياس الكهربائي والظروف الميكروفيزيائية والديناميكية والبيئية، مع التمييز بين الإشارة المقاسة والاستنتاج الفيزيائي."},{"type":"heading","text":"البيانات والأجهزة"},{"type":"list","items":["المجال الكهربائي والجهد والتيار أو الموصلية بحسب الجهاز.","إشارات المستشعرات الكهرومغناطيسية أو البصرية وتوقيتها.","بيانات الرادار والأقمار الصناعية والطقس السطحي.","موقع المحطات وهندستها ومعايرتها وحالة الاتصال.","سجلات الأحداث الخام وبيانات ضبط الجودة."]},{"type":"heading","text":"منهجية التحليل"},{"type":"list","items":["حدد الظاهرة ونوع الإشارة التي يقيسها الجهاز مباشرة.","تحقق من التوقيت والمعايرة وحدود الكشف.","اربط الإشارة بالبنية السحابية والبيئة الجوية.","ادمج مصادر الرصد مع توحيد الإسقاط والزمن.","اعرض عدم اليقين والتغطية ومعدل الأحداث غير المكتشفة."]},{"type":"heading","text":"مثال تطبيقي"},{"type":"example","title":"عدم اليقين في تحديد مواقع البرق","text":"ضع قائمة بالعوامل التي تزيد عدم اليقين المكاني لشبكة كشف البرق. استخدم حالة افتراضية تعليمية، وبيّن ما يمكن استنتاجه وما يحتاج إلى قياسات إضافية."},{"type":"heading","text":"المهمة العملية"},{"type":"text","text":"ضع قائمة بالعوامل التي تزيد عدم اليقين المكاني لشبكة كشف البرق."},{"type":"heading","text":"أخطاء شائعة"},{"type":"list","items":["اعتبار كل إشارة كهربائية حدث برق مؤكداً.","إهمال كفاءة الكشف وتغيرها مع الزمن.","الخلط بين كثافة الأحداث ومستوى الخطر المحلي.","دمج مصادر غير متزامنة دون توثيق الفروق الزمنية.","إسناد اتجاه مناخي قبل فحص تجانس شبكة الرصد."]},{"type":"callout","text":"تفسير البرق والكهرباء الجوية يتطلب شبكة رصد معايرة وسياقاً جوياً متكاملاً، لا مجرد عرض نقاط على الخريطة."},{"type":"heading","text":"الخلاصة"},{"type":"text","text":"يوفر الرصد الكهربائي بعداً إضافياً لفهم العواصف والهباء والغلاف الجوي. وتنبع القيمة التشغيلية من تكامل المستشعرات وضبط الجودة والتفسير متعدد المصادر."}]}'::jsonb,8640,55,'["شرح الآلية الكهربائية الجوية أو مبدأ الرصد المرتبط بالموضوع","تحليل بيانات المستشعرات وربطها بالسياق الجوي","تقييم جودة الشبكة ومصادر عدم اليقين في المنتجات"]'::jsonb,'الكهرباء الجوية وتكهرب السحب'),
('lightning-density-climatology','مناخية كثافة البرق','التوزيع المكاني والموسمي','{"blocks":[{"type":"heading","text":"المفهوم العلمي"},{"type":"text","text":"تصف مناخية البرق التغير المكاني والموسمي لمعدل التفريغات، وتحتاج إلى فترة رصد كافية وتوحيد تعريف الحدث وتصحيح تغير كفاءة الشبكة. لا تعني كثافة البرق وحدها مستوى الخطر الكامل."},{"type":"heading","text":"الأساس الفيزيائي"},{"type":"text","text":"تنتج الظواهر الكهربائية الجوية من حركة الشحنات وفصلها وانتقالها ضمن وسط غازي متغير الموصلية. ويتطلب تفسيرها الجمع بين القياس الكهربائي والظروف الميكروفيزيائية والديناميكية والبيئية، مع التمييز بين الإشارة المقاسة والاستنتاج الفيزيائي."},{"type":"heading","text":"البيانات والأجهزة"},{"type":"list","items":["المجال الكهربائي والجهد والتيار أو الموصلية بحسب الجهاز.","إشارات المستشعرات الكهرومغناطيسية أو البصرية وتوقيتها.","بيانات الرادار والأقمار الصناعية والطقس السطحي.","موقع المحطات وهندستها ومعايرتها وحالة الاتصال.","سجلات الأحداث الخام وبيانات ضبط الجودة."]},{"type":"heading","text":"منهجية التحليل"},{"type":"list","items":["حدد الظاهرة ونوع الإشارة التي يقيسها الجهاز مباشرة.","تحقق من التوقيت والمعايرة وحدود الكشف.","اربط الإشارة بالبنية السحابية والبيئة الجوية.","ادمج مصادر الرصد مع توحيد الإسقاط والزمن.","اعرض عدم اليقين والتغطية ومعدل الأحداث غير المكتشفة."]},{"type":"heading","text":"مثال تطبيقي"},{"type":"example","title":"مناخية كثافة البرق","text":"اقترح طريقة لمقارنة كثافة البرق بين منطقتين مع اختلاف مدة الرصد. استخدم حالة افتراضية تعليمية، وبيّن ما يمكن استنتاجه وما يحتاج إلى قياسات إضافية."},{"type":"heading","text":"المهمة العملية"},{"type":"text","text":"اقترح طريقة لمقارنة كثافة البرق بين منطقتين مع اختلاف مدة الرصد."},{"type":"heading","text":"أخطاء شائعة"},{"type":"list","items":["اعتبار كل إشارة كهربائية حدث برق مؤكداً.","إهمال كفاءة الكشف وتغيرها مع الزمن.","الخلط بين كثافة الأحداث ومستوى الخطر المحلي.","دمج مصادر غير متزامنة دون توثيق الفروق الزمنية.","إسناد اتجاه مناخي قبل فحص تجانس شبكة الرصد."]},{"type":"callout","text":"تفسير البرق والكهرباء الجوية يتطلب شبكة رصد معايرة وسياقاً جوياً متكاملاً، لا مجرد عرض نقاط على الخريطة."},{"type":"heading","text":"الخلاصة"},{"type":"text","text":"يوفر الرصد الكهربائي بعداً إضافياً لفهم العواصف والهباء والغلاف الجوي. وتنبع القيمة التشغيلية من تكامل المستشعرات وضبط الجودة والتفسير متعدد المصادر."}]}'::jsonb,8650,55,'["شرح الآلية الكهربائية الجوية أو مبدأ الرصد المرتبط بالموضوع","تحليل بيانات المستشعرات وربطها بالسياق الجوي","تقييم جودة الشبكة ومصادر عدم اليقين في المنتجات"]'::jsonb,'الكهرباء الجوية وتكهرب السحب'),
('lightning-nowcasting-signals','إشارات البرق في التنبؤ الآني بالعواصف','معدل التفريغ والتغير الزمني','{"blocks":[{"type":"heading","text":"المفهوم العلمي"},{"type":"text","text":"يمكن أن تقدم تغيرات نشاط البرق مؤشرات عن تطور بعض العواصف، لكن تفسيرها يجب أن يدمج مع الرادار والأقمار الصناعية والبيئة الديناميكية. تختلف العلاقة بين البرق وشدة الهطول من حالة إلى أخرى."},{"type":"heading","text":"الأساس الفيزيائي"},{"type":"text","text":"تنتج الظواهر الكهربائية الجوية من حركة الشحنات وفصلها وانتقالها ضمن وسط غازي متغير الموصلية. ويتطلب تفسيرها الجمع بين القياس الكهربائي والظروف الميكروفيزيائية والديناميكية والبيئية، مع التمييز بين الإشارة المقاسة والاستنتاج الفيزيائي."},{"type":"heading","text":"البيانات والأجهزة"},{"type":"list","items":["المجال الكهربائي والجهد والتيار أو الموصلية بحسب الجهاز.","إشارات المستشعرات الكهرومغناطيسية أو البصرية وتوقيتها.","بيانات الرادار والأقمار الصناعية والطقس السطحي.","موقع المحطات وهندستها ومعايرتها وحالة الاتصال.","سجلات الأحداث الخام وبيانات ضبط الجودة."]},{"type":"heading","text":"منهجية التحليل"},{"type":"list","items":["حدد الظاهرة ونوع الإشارة التي يقيسها الجهاز مباشرة.","تحقق من التوقيت والمعايرة وحدود الكشف.","اربط الإشارة بالبنية السحابية والبيئة الجوية.","ادمج مصادر الرصد مع توحيد الإسقاط والزمن.","اعرض عدم اليقين والتغطية ومعدل الأحداث غير المكتشفة."]},{"type":"heading","text":"مثال تطبيقي"},{"type":"example","title":"إشارات البرق في التنبؤ الآني بالعواصف","text":"صمم لوحة مؤشرات تجمع اتجاه نشاط البرق مع الرادار دون اعتماد منفرد. استخدم حالة افتراضية تعليمية، وبيّن ما يمكن استنتاجه وما يحتاج إلى قياسات إضافية."},{"type":"heading","text":"المهمة العملية"},{"type":"text","text":"صمم لوحة مؤشرات تجمع اتجاه نشاط البرق مع الرادار دون اعتماد منفرد."},{"type":"heading","text":"أخطاء شائعة"},{"type":"list","items":["اعتبار كل إشارة كهربائية حدث برق مؤكداً.","إهمال كفاءة الكشف وتغيرها مع الزمن.","الخلط بين كثافة الأحداث ومستوى الخطر المحلي.","دمج مصادر غير متزامنة دون توثيق الفروق الزمنية.","إسناد اتجاه مناخي قبل فحص تجانس شبكة الرصد."]},{"type":"callout","text":"تفسير البرق والكهرباء الجوية يتطلب شبكة رصد معايرة وسياقاً جوياً متكاملاً، لا مجرد عرض نقاط على الخريطة."},{"type":"heading","text":"الخلاصة"},{"type":"text","text":"يوفر الرصد الكهربائي بعداً إضافياً لفهم العواصف والهباء والغلاف الجوي. وتنبع القيمة التشغيلية من تكامل المستشعرات وضبط الجودة والتفسير متعدد المصادر."}]}'::jsonb,8660,55,'["شرح الآلية الكهربائية الجوية أو مبدأ الرصد المرتبط بالموضوع","تحليل بيانات المستشعرات وربطها بالسياق الجوي","تقييم جودة الشبكة ومصادر عدم اليقين في المنتجات"]'::jsonb,'شبكات كشف البرق والتحليل التشغيلي'),
('lightning-radar-satellite-fusion','دمج البرق مع الرادار والأقمار الصناعية','التكامل متعدد المستشعرات','{"blocks":[{"type":"heading","text":"المفهوم العلمي"},{"type":"text","text":"يوفر الرادار بنية الهطول والانعكاسية، وتكشف الأقمار عن قمم السحب وخصائصها، بينما تضيف شبكة البرق معلومات كهربائية زمنية. يتطلب الدمج توحيد التوقيت والإسقاط والمقياس."},{"type":"heading","text":"الأساس الفيزيائي"},{"type":"text","text":"تنتج الظواهر الكهربائية الجوية من حركة الشحنات وفصلها وانتقالها ضمن وسط غازي متغير الموصلية. ويتطلب تفسيرها الجمع بين القياس الكهربائي والظروف الميكروفيزيائية والديناميكية والبيئية، مع التمييز بين الإشارة المقاسة والاستنتاج الفيزيائي."},{"type":"heading","text":"البيانات والأجهزة"},{"type":"list","items":["المجال الكهربائي والجهد والتيار أو الموصلية بحسب الجهاز.","إشارات المستشعرات الكهرومغناطيسية أو البصرية وتوقيتها.","بيانات الرادار والأقمار الصناعية والطقس السطحي.","موقع المحطات وهندستها ومعايرتها وحالة الاتصال.","سجلات الأحداث الخام وبيانات ضبط الجودة."]},{"type":"heading","text":"منهجية التحليل"},{"type":"list","items":["حدد الظاهرة ونوع الإشارة التي يقيسها الجهاز مباشرة.","تحقق من التوقيت والمعايرة وحدود الكشف.","اربط الإشارة بالبنية السحابية والبيئة الجوية.","ادمج مصادر الرصد مع توحيد الإسقاط والزمن.","اعرض عدم اليقين والتغطية ومعدل الأحداث غير المكتشفة."]},{"type":"heading","text":"مثال تطبيقي"},{"type":"example","title":"دمج البرق مع الرادار والأقمار الصناعية","text":"حدد خطوات مواءمة ثلاثة مصادر رصد في خريطة زمنية واحدة. استخدم حالة افتراضية تعليمية، وبيّن ما يمكن استنتاجه وما يحتاج إلى قياسات إضافية."},{"type":"heading","text":"المهمة العملية"},{"type":"text","text":"حدد خطوات مواءمة ثلاثة مصادر رصد في خريطة زمنية واحدة."},{"type":"heading","text":"أخطاء شائعة"},{"type":"list","items":["اعتبار كل إشارة كهربائية حدث برق مؤكداً.","إهمال كفاءة الكشف وتغيرها مع الزمن.","الخلط بين كثافة الأحداث ومستوى الخطر المحلي.","دمج مصادر غير متزامنة دون توثيق الفروق الزمنية.","إسناد اتجاه مناخي قبل فحص تجانس شبكة الرصد."]},{"type":"callout","text":"تفسير البرق والكهرباء الجوية يتطلب شبكة رصد معايرة وسياقاً جوياً متكاملاً، لا مجرد عرض نقاط على الخريطة."},{"type":"heading","text":"الخلاصة"},{"type":"text","text":"يوفر الرصد الكهربائي بعداً إضافياً لفهم العواصف والهباء والغلاف الجوي. وتنبع القيمة التشغيلية من تكامل المستشعرات وضبط الجودة والتفسير متعدد المصادر."}]}'::jsonb,8670,55,'["شرح الآلية الكهربائية الجوية أو مبدأ الرصد المرتبط بالموضوع","تحليل بيانات المستشعرات وربطها بالسياق الجوي","تقييم جودة الشبكة ومصادر عدم اليقين في المنتجات"]'::jsonb,'شبكات كشف البرق والتحليل التشغيلي'),
('thunderstorm-life-cycle-electrical','التطور الكهربائي خلال دورة حياة العاصفة','النشوء والنضج والاضمحلال','{"blocks":[{"type":"heading","text":"المفهوم العلمي"},{"type":"text","text":"يتغير النشاط الكهربائي مع تطور السحابة والحمل الحراري وتوزيع الجليد والشحنات. قد تختلف مؤشرات البرق بين مراحل العاصفة، ويجب تفسيرها مع بنية الخلية وبيئتها."},{"type":"heading","text":"الأساس الفيزيائي"},{"type":"text","text":"تنتج الظواهر الكهربائية الجوية من حركة الشحنات وفصلها وانتقالها ضمن وسط غازي متغير الموصلية. ويتطلب تفسيرها الجمع بين القياس الكهربائي والظروف الميكروفيزيائية والديناميكية والبيئية، مع التمييز بين الإشارة المقاسة والاستنتاج الفيزيائي."},{"type":"heading","text":"البيانات والأجهزة"},{"type":"list","items":["المجال الكهربائي والجهد والتيار أو الموصلية بحسب الجهاز.","إشارات المستشعرات الكهرومغناطيسية أو البصرية وتوقيتها.","بيانات الرادار والأقمار الصناعية والطقس السطحي.","موقع المحطات وهندستها ومعايرتها وحالة الاتصال.","سجلات الأحداث الخام وبيانات ضبط الجودة."]},{"type":"heading","text":"منهجية التحليل"},{"type":"list","items":["حدد الظاهرة ونوع الإشارة التي يقيسها الجهاز مباشرة.","تحقق من التوقيت والمعايرة وحدود الكشف.","اربط الإشارة بالبنية السحابية والبيئة الجوية.","ادمج مصادر الرصد مع توحيد الإسقاط والزمن.","اعرض عدم اليقين والتغطية ومعدل الأحداث غير المكتشفة."]},{"type":"heading","text":"مثال تطبيقي"},{"type":"example","title":"التطور الكهربائي خلال دورة حياة العاصفة","text":"قارن خصائص الرصد المتوقعة في مراحل مختلفة من عمر العاصفة. استخدم حالة افتراضية تعليمية، وبيّن ما يمكن استنتاجه وما يحتاج إلى قياسات إضافية."},{"type":"heading","text":"المهمة العملية"},{"type":"text","text":"قارن خصائص الرصد المتوقعة في مراحل مختلفة من عمر العاصفة."},{"type":"heading","text":"أخطاء شائعة"},{"type":"list","items":["اعتبار كل إشارة كهربائية حدث برق مؤكداً.","إهمال كفاءة الكشف وتغيرها مع الزمن.","الخلط بين كثافة الأحداث ومستوى الخطر المحلي.","دمج مصادر غير متزامنة دون توثيق الفروق الزمنية.","إسناد اتجاه مناخي قبل فحص تجانس شبكة الرصد."]},{"type":"callout","text":"تفسير البرق والكهرباء الجوية يتطلب شبكة رصد معايرة وسياقاً جوياً متكاملاً، لا مجرد عرض نقاط على الخريطة."},{"type":"heading","text":"الخلاصة"},{"type":"text","text":"يوفر الرصد الكهربائي بعداً إضافياً لفهم العواصف والهباء والغلاف الجوي. وتنبع القيمة التشغيلية من تكامل المستشعرات وضبط الجودة والتفسير متعدد المصادر."}]}'::jsonb,8680,55,'["شرح الآلية الكهربائية الجوية أو مبدأ الرصد المرتبط بالموضوع","تحليل بيانات المستشعرات وربطها بالسياق الجوي","تقييم جودة الشبكة ومصادر عدم اليقين في المنتجات"]'::jsonb,'شبكات كشف البرق والتحليل التشغيلي'),
('volcanic-dust-electrification','التكهرب في أعمدة الغبار والرماد','الاحتكاك والتصادم والجسيمات','{"blocks":[{"type":"heading","text":"المفهوم العلمي"},{"type":"text","text":"قد تتولد شحنات كهربائية في أعمدة الغبار والرماد نتيجة التصادم والاحتكاك وفصل الجسيمات، وتختلف الآليات بحسب تركيبها وحجمها ورطوبتها. تعد القياسات الميدانية والفضائية ضرورية لتوصيف الظاهرة."},{"type":"heading","text":"الأساس الفيزيائي"},{"type":"text","text":"تنتج الظواهر الكهربائية الجوية من حركة الشحنات وفصلها وانتقالها ضمن وسط غازي متغير الموصلية. ويتطلب تفسيرها الجمع بين القياس الكهربائي والظروف الميكروفيزيائية والديناميكية والبيئية، مع التمييز بين الإشارة المقاسة والاستنتاج الفيزيائي."},{"type":"heading","text":"البيانات والأجهزة"},{"type":"list","items":["المجال الكهربائي والجهد والتيار أو الموصلية بحسب الجهاز.","إشارات المستشعرات الكهرومغناطيسية أو البصرية وتوقيتها.","بيانات الرادار والأقمار الصناعية والطقس السطحي.","موقع المحطات وهندستها ومعايرتها وحالة الاتصال.","سجلات الأحداث الخام وبيانات ضبط الجودة."]},{"type":"heading","text":"منهجية التحليل"},{"type":"list","items":["حدد الظاهرة ونوع الإشارة التي يقيسها الجهاز مباشرة.","تحقق من التوقيت والمعايرة وحدود الكشف.","اربط الإشارة بالبنية السحابية والبيئة الجوية.","ادمج مصادر الرصد مع توحيد الإسقاط والزمن.","اعرض عدم اليقين والتغطية ومعدل الأحداث غير المكتشفة."]},{"type":"heading","text":"مثال تطبيقي"},{"type":"example","title":"التكهرب في أعمدة الغبار والرماد","text":"اشرح كيف يمكن لتوزيع أحجام الجسيمات أن يؤثر في فصل الشحنة. استخدم حالة افتراضية تعليمية، وبيّن ما يمكن استنتاجه وما يحتاج إلى قياسات إضافية."},{"type":"heading","text":"المهمة العملية"},{"type":"text","text":"اشرح كيف يمكن لتوزيع أحجام الجسيمات أن يؤثر في فصل الشحنة."},{"type":"heading","text":"أخطاء شائعة"},{"type":"list","items":["اعتبار كل إشارة كهربائية حدث برق مؤكداً.","إهمال كفاءة الكشف وتغيرها مع الزمن.","الخلط بين كثافة الأحداث ومستوى الخطر المحلي.","دمج مصادر غير متزامنة دون توثيق الفروق الزمنية.","إسناد اتجاه مناخي قبل فحص تجانس شبكة الرصد."]},{"type":"callout","text":"تفسير البرق والكهرباء الجوية يتطلب شبكة رصد معايرة وسياقاً جوياً متكاملاً، لا مجرد عرض نقاط على الخريطة."},{"type":"heading","text":"الخلاصة"},{"type":"text","text":"يوفر الرصد الكهربائي بعداً إضافياً لفهم العواصف والهباء والغلاف الجوي. وتنبع القيمة التشغيلية من تكامل المستشعرات وضبط الجودة والتفسير متعدد المصادر."}]}'::jsonb,8690,55,'["شرح الآلية الكهربائية الجوية أو مبدأ الرصد المرتبط بالموضوع","تحليل بيانات المستشعرات وربطها بالسياق الجوي","تقييم جودة الشبكة ومصادر عدم اليقين في المنتجات"]'::jsonb,'شبكات كشف البرق والتحليل التشغيلي'),
('dust-storm-electrical-observations','رصد الكهرباء المصاحبة للعواصف الغبارية','المجال الكهربائي والجسيمات والطقس','{"blocks":[{"type":"heading","text":"المفهوم العلمي"},{"type":"text","text":"يمكن أن ترافق العواصف الغبارية تغيرات في المجال الكهربائي بسبب حركة الجسيمات وتفاعلاتها. يجب ربط القياسات الكهربائية بسرعة الرياح وتركيز الغبار والرطوبة والموقع لتجنب التفسيرات المنفردة."},{"type":"heading","text":"الأساس الفيزيائي"},{"type":"text","text":"تنتج الظواهر الكهربائية الجوية من حركة الشحنات وفصلها وانتقالها ضمن وسط غازي متغير الموصلية. ويتطلب تفسيرها الجمع بين القياس الكهربائي والظروف الميكروفيزيائية والديناميكية والبيئية، مع التمييز بين الإشارة المقاسة والاستنتاج الفيزيائي."},{"type":"heading","text":"البيانات والأجهزة"},{"type":"list","items":["المجال الكهربائي والجهد والتيار أو الموصلية بحسب الجهاز.","إشارات المستشعرات الكهرومغناطيسية أو البصرية وتوقيتها.","بيانات الرادار والأقمار الصناعية والطقس السطحي.","موقع المحطات وهندستها ومعايرتها وحالة الاتصال.","سجلات الأحداث الخام وبيانات ضبط الجودة."]},{"type":"heading","text":"منهجية التحليل"},{"type":"list","items":["حدد الظاهرة ونوع الإشارة التي يقيسها الجهاز مباشرة.","تحقق من التوقيت والمعايرة وحدود الكشف.","اربط الإشارة بالبنية السحابية والبيئة الجوية.","ادمج مصادر الرصد مع توحيد الإسقاط والزمن.","اعرض عدم اليقين والتغطية ومعدل الأحداث غير المكتشفة."]},{"type":"heading","text":"مثال تطبيقي"},{"type":"example","title":"رصد الكهرباء المصاحبة للعواصف الغبارية","text":"اقترح مجموعة قياسات متزامنة لدراسة عاصفة غبارية كهربائياً. استخدم حالة افتراضية تعليمية، وبيّن ما يمكن استنتاجه وما يحتاج إلى قياسات إضافية."},{"type":"heading","text":"المهمة العملية"},{"type":"text","text":"اقترح مجموعة قياسات متزامنة لدراسة عاصفة غبارية كهربائياً."},{"type":"heading","text":"أخطاء شائعة"},{"type":"list","items":["اعتبار كل إشارة كهربائية حدث برق مؤكداً.","إهمال كفاءة الكشف وتغيرها مع الزمن.","الخلط بين كثافة الأحداث ومستوى الخطر المحلي.","دمج مصادر غير متزامنة دون توثيق الفروق الزمنية.","إسناد اتجاه مناخي قبل فحص تجانس شبكة الرصد."]},{"type":"callout","text":"تفسير البرق والكهرباء الجوية يتطلب شبكة رصد معايرة وسياقاً جوياً متكاملاً، لا مجرد عرض نقاط على الخريطة."},{"type":"heading","text":"الخلاصة"},{"type":"text","text":"يوفر الرصد الكهربائي بعداً إضافياً لفهم العواصف والهباء والغلاف الجوي. وتنبع القيمة التشغيلية من تكامل المستشعرات وضبط الجودة والتفسير متعدد المصادر."}]}'::jsonb,8700,55,'["شرح الآلية الكهربائية الجوية أو مبدأ الرصد المرتبط بالموضوع","تحليل بيانات المستشعرات وربطها بالسياق الجوي","تقييم جودة الشبكة ومصادر عدم اليقين في المنتجات"]'::jsonb,'شبكات كشف البرق والتحليل التشغيلي'),
('atmospheric-conductivity-aerosols','الموصلية الجوية وعلاقتها بالهباء','الأيونات والجسيمات العالقة','{"blocks":[{"type":"heading","text":"المفهوم العلمي"},{"type":"text","text":"تعتمد موصلية الهواء على الأيونات الصغيرة وحركيتها والتقاطها بواسطة الهباء. تؤثر تراكيز الجسيمات وحجمها وتركيبها والرطوبة في التوازن الأيوني، وتختلف القياسات قرب المصادر الملوثة."},{"type":"heading","text":"الأساس الفيزيائي"},{"type":"text","text":"تنتج الظواهر الكهربائية الجوية من حركة الشحنات وفصلها وانتقالها ضمن وسط غازي متغير الموصلية. ويتطلب تفسيرها الجمع بين القياس الكهربائي والظروف الميكروفيزيائية والديناميكية والبيئية، مع التمييز بين الإشارة المقاسة والاستنتاج الفيزيائي."},{"type":"heading","text":"البيانات والأجهزة"},{"type":"list","items":["المجال الكهربائي والجهد والتيار أو الموصلية بحسب الجهاز.","إشارات المستشعرات الكهرومغناطيسية أو البصرية وتوقيتها.","بيانات الرادار والأقمار الصناعية والطقس السطحي.","موقع المحطات وهندستها ومعايرتها وحالة الاتصال.","سجلات الأحداث الخام وبيانات ضبط الجودة."]},{"type":"heading","text":"منهجية التحليل"},{"type":"list","items":["حدد الظاهرة ونوع الإشارة التي يقيسها الجهاز مباشرة.","تحقق من التوقيت والمعايرة وحدود الكشف.","اربط الإشارة بالبنية السحابية والبيئة الجوية.","ادمج مصادر الرصد مع توحيد الإسقاط والزمن.","اعرض عدم اليقين والتغطية ومعدل الأحداث غير المكتشفة."]},{"type":"heading","text":"مثال تطبيقي"},{"type":"example","title":"الموصلية الجوية وعلاقتها بالهباء","text":"حلل بصورة مفاهيمية كيف قد يغير ارتفاع تركيز الهباء الموصلية. استخدم حالة افتراضية تعليمية، وبيّن ما يمكن استنتاجه وما يحتاج إلى قياسات إضافية."},{"type":"heading","text":"المهمة العملية"},{"type":"text","text":"حلل بصورة مفاهيمية كيف قد يغير ارتفاع تركيز الهباء الموصلية."},{"type":"heading","text":"أخطاء شائعة"},{"type":"list","items":["اعتبار كل إشارة كهربائية حدث برق مؤكداً.","إهمال كفاءة الكشف وتغيرها مع الزمن.","الخلط بين كثافة الأحداث ومستوى الخطر المحلي.","دمج مصادر غير متزامنة دون توثيق الفروق الزمنية.","إسناد اتجاه مناخي قبل فحص تجانس شبكة الرصد."]},{"type":"callout","text":"تفسير البرق والكهرباء الجوية يتطلب شبكة رصد معايرة وسياقاً جوياً متكاملاً، لا مجرد عرض نقاط على الخريطة."},{"type":"heading","text":"الخلاصة"},{"type":"text","text":"يوفر الرصد الكهربائي بعداً إضافياً لفهم العواصف والهباء والغلاف الجوي. وتنبع القيمة التشغيلية من تكامل المستشعرات وضبط الجودة والتفسير متعدد المصادر."}]}'::jsonb,8710,55,'["شرح الآلية الكهربائية الجوية أو مبدأ الرصد المرتبط بالموضوع","تحليل بيانات المستشعرات وربطها بالسياق الجوي","تقييم جودة الشبكة ومصادر عدم اليقين في المنتجات"]'::jsonb,'شبكات كشف البرق والتحليل التشغيلي'),
('lightning-sensor-calibration','معايرة مستشعرات كشف البرق','الحساسية والاستجابة والتوقيت','{"blocks":[{"type":"heading","text":"المفهوم العلمي"},{"type":"text","text":"تتطلب معايرة المستشعرات التحقق من الاستجابة والتوقيت والحساسية ومعدل الإنذارات الكاذبة. ويجب توثيق التغيرات في الأجهزة والبرمجيات حتى لا تفسر على أنها تغير مناخي حقيقي."},{"type":"heading","text":"الأساس الفيزيائي"},{"type":"text","text":"تنتج الظواهر الكهربائية الجوية من حركة الشحنات وفصلها وانتقالها ضمن وسط غازي متغير الموصلية. ويتطلب تفسيرها الجمع بين القياس الكهربائي والظروف الميكروفيزيائية والديناميكية والبيئية، مع التمييز بين الإشارة المقاسة والاستنتاج الفيزيائي."},{"type":"heading","text":"البيانات والأجهزة"},{"type":"list","items":["المجال الكهربائي والجهد والتيار أو الموصلية بحسب الجهاز.","إشارات المستشعرات الكهرومغناطيسية أو البصرية وتوقيتها.","بيانات الرادار والأقمار الصناعية والطقس السطحي.","موقع المحطات وهندستها ومعايرتها وحالة الاتصال.","سجلات الأحداث الخام وبيانات ضبط الجودة."]},{"type":"heading","text":"منهجية التحليل"},{"type":"list","items":["حدد الظاهرة ونوع الإشارة التي يقيسها الجهاز مباشرة.","تحقق من التوقيت والمعايرة وحدود الكشف.","اربط الإشارة بالبنية السحابية والبيئة الجوية.","ادمج مصادر الرصد مع توحيد الإسقاط والزمن.","اعرض عدم اليقين والتغطية ومعدل الأحداث غير المكتشفة."]},{"type":"heading","text":"مثال تطبيقي"},{"type":"example","title":"معايرة مستشعرات كشف البرق","text":"صمم سجل معايرة ومراقبة أداء لشبكة كشف البرق. استخدم حالة افتراضية تعليمية، وبيّن ما يمكن استنتاجه وما يحتاج إلى قياسات إضافية."},{"type":"heading","text":"المهمة العملية"},{"type":"text","text":"صمم سجل معايرة ومراقبة أداء لشبكة كشف البرق."},{"type":"heading","text":"أخطاء شائعة"},{"type":"list","items":["اعتبار كل إشارة كهربائية حدث برق مؤكداً.","إهمال كفاءة الكشف وتغيرها مع الزمن.","الخلط بين كثافة الأحداث ومستوى الخطر المحلي.","دمج مصادر غير متزامنة دون توثيق الفروق الزمنية.","إسناد اتجاه مناخي قبل فحص تجانس شبكة الرصد."]},{"type":"callout","text":"تفسير البرق والكهرباء الجوية يتطلب شبكة رصد معايرة وسياقاً جوياً متكاملاً، لا مجرد عرض نقاط على الخريطة."},{"type":"heading","text":"الخلاصة"},{"type":"text","text":"يوفر الرصد الكهربائي بعداً إضافياً لفهم العواصف والهباء والغلاف الجوي. وتنبع القيمة التشغيلية من تكامل المستشعرات وضبط الجودة والتفسير متعدد المصادر."}]}'::jsonb,8720,55,'["شرح الآلية الكهربائية الجوية أو مبدأ الرصد المرتبط بالموضوع","تحليل بيانات المستشعرات وربطها بالسياق الجوي","تقييم جودة الشبكة ومصادر عدم اليقين في المنتجات"]'::jsonb,'شبكات كشف البرق والتحليل التشغيلي'),
('lightning-data-quality-control','ضبط جودة بيانات البرق','كشف التكرار والشذوذ وتجانس السجل','{"blocks":[{"type":"heading","text":"المفهوم العلمي"},{"type":"text","text":"تشمل مراقبة الجودة كشف الأحداث المكررة والمواقع غير المعقولة والانحرافات الزمنية وتغير كفاءة المستشعرات. ينبغي الحفاظ على البيانات الخام وإنتاج طبقة منقحة موثقة."},{"type":"heading","text":"الأساس الفيزيائي"},{"type":"text","text":"تنتج الظواهر الكهربائية الجوية من حركة الشحنات وفصلها وانتقالها ضمن وسط غازي متغير الموصلية. ويتطلب تفسيرها الجمع بين القياس الكهربائي والظروف الميكروفيزيائية والديناميكية والبيئية، مع التمييز بين الإشارة المقاسة والاستنتاج الفيزيائي."},{"type":"heading","text":"البيانات والأجهزة"},{"type":"list","items":["المجال الكهربائي والجهد والتيار أو الموصلية بحسب الجهاز.","إشارات المستشعرات الكهرومغناطيسية أو البصرية وتوقيتها.","بيانات الرادار والأقمار الصناعية والطقس السطحي.","موقع المحطات وهندستها ومعايرتها وحالة الاتصال.","سجلات الأحداث الخام وبيانات ضبط الجودة."]},{"type":"heading","text":"منهجية التحليل"},{"type":"list","items":["حدد الظاهرة ونوع الإشارة التي يقيسها الجهاز مباشرة.","تحقق من التوقيت والمعايرة وحدود الكشف.","اربط الإشارة بالبنية السحابية والبيئة الجوية.","ادمج مصادر الرصد مع توحيد الإسقاط والزمن.","اعرض عدم اليقين والتغطية ومعدل الأحداث غير المكتشفة."]},{"type":"heading","text":"مثال تطبيقي"},{"type":"example","title":"ضبط جودة بيانات البرق","text":"ضع قواعد تحقق أولية لسجل أحداث برق متعدد المحطات. استخدم حالة افتراضية تعليمية، وبيّن ما يمكن استنتاجه وما يحتاج إلى قياسات إضافية."},{"type":"heading","text":"المهمة العملية"},{"type":"text","text":"ضع قواعد تحقق أولية لسجل أحداث برق متعدد المحطات."},{"type":"heading","text":"أخطاء شائعة"},{"type":"list","items":["اعتبار كل إشارة كهربائية حدث برق مؤكداً.","إهمال كفاءة الكشف وتغيرها مع الزمن.","الخلط بين كثافة الأحداث ومستوى الخطر المحلي.","دمج مصادر غير متزامنة دون توثيق الفروق الزمنية.","إسناد اتجاه مناخي قبل فحص تجانس شبكة الرصد."]},{"type":"callout","text":"تفسير البرق والكهرباء الجوية يتطلب شبكة رصد معايرة وسياقاً جوياً متكاملاً، لا مجرد عرض نقاط على الخريطة."},{"type":"heading","text":"الخلاصة"},{"type":"text","text":"يوفر الرصد الكهربائي بعداً إضافياً لفهم العواصف والهباء والغلاف الجوي. وتنبع القيمة التشغيلية من تكامل المستشعرات وضبط الجودة والتفسير متعدد المصادر."}]}'::jsonb,8730,55,'["شرح الآلية الكهربائية الجوية أو مبدأ الرصد المرتبط بالموضوع","تحليل بيانات المستشعرات وربطها بالسياق الجوي","تقييم جودة الشبكة ومصادر عدم اليقين في المنتجات"]'::jsonb,'شبكات كشف البرق والتحليل التشغيلي'),
('lightning-climate-trends','تحليل اتجاهات البرق طويلة الأمد','تجانس الشبكة والتغير المناخي','{"blocks":[{"type":"heading","text":"المفهوم العلمي"},{"type":"text","text":"يتطلب تحليل اتجاهات البرق سلسلة متجانسة أو تصحيح تغيرات كفاءة الكشف ومواقع المستشعرات. كما ينبغي مراعاة التغير في تعريف الحدث والتغطية ومصادر البيانات قبل إسناد أي اتجاه إلى المناخ."},{"type":"heading","text":"الأساس الفيزيائي"},{"type":"text","text":"تنتج الظواهر الكهربائية الجوية من حركة الشحنات وفصلها وانتقالها ضمن وسط غازي متغير الموصلية. ويتطلب تفسيرها الجمع بين القياس الكهربائي والظروف الميكروفيزيائية والديناميكية والبيئية، مع التمييز بين الإشارة المقاسة والاستنتاج الفيزيائي."},{"type":"heading","text":"البيانات والأجهزة"},{"type":"list","items":["المجال الكهربائي والجهد والتيار أو الموصلية بحسب الجهاز.","إشارات المستشعرات الكهرومغناطيسية أو البصرية وتوقيتها.","بيانات الرادار والأقمار الصناعية والطقس السطحي.","موقع المحطات وهندستها ومعايرتها وحالة الاتصال.","سجلات الأحداث الخام وبيانات ضبط الجودة."]},{"type":"heading","text":"منهجية التحليل"},{"type":"list","items":["حدد الظاهرة ونوع الإشارة التي يقيسها الجهاز مباشرة.","تحقق من التوقيت والمعايرة وحدود الكشف.","اربط الإشارة بالبنية السحابية والبيئة الجوية.","ادمج مصادر الرصد مع توحيد الإسقاط والزمن.","اعرض عدم اليقين والتغطية ومعدل الأحداث غير المكتشفة."]},{"type":"heading","text":"مثال تطبيقي"},{"type":"example","title":"تحليل اتجاهات البرق طويلة الأمد","text":"اشرح كيف يمكن لتوسيع شبكة الكشف أن يصنع اتجاهاً ظاهرياً في السجل. استخدم حالة افتراضية تعليمية، وبيّن ما يمكن استنتاجه وما يحتاج إلى قياسات إضافية."},{"type":"heading","text":"المهمة العملية"},{"type":"text","text":"اشرح كيف يمكن لتوسيع شبكة الكشف أن يصنع اتجاهاً ظاهرياً في السجل."},{"type":"heading","text":"أخطاء شائعة"},{"type":"list","items":["اعتبار كل إشارة كهربائية حدث برق مؤكداً.","إهمال كفاءة الكشف وتغيرها مع الزمن.","الخلط بين كثافة الأحداث ومستوى الخطر المحلي.","دمج مصادر غير متزامنة دون توثيق الفروق الزمنية.","إسناد اتجاه مناخي قبل فحص تجانس شبكة الرصد."]},{"type":"callout","text":"تفسير البرق والكهرباء الجوية يتطلب شبكة رصد معايرة وسياقاً جوياً متكاملاً، لا مجرد عرض نقاط على الخريطة."},{"type":"heading","text":"الخلاصة"},{"type":"text","text":"يوفر الرصد الكهربائي بعداً إضافياً لفهم العواصف والهباء والغلاف الجوي. وتنبع القيمة التشغيلية من تكامل المستشعرات وضبط الجودة والتفسير متعدد المصادر."}]}'::jsonb,8740,55,'["شرح الآلية الكهربائية الجوية أو مبدأ الرصد المرتبط بالموضوع","تحليل بيانات المستشعرات وربطها بالسياق الجوي","تقييم جودة الشبكة ومصادر عدم اليقين في المنتجات"]'::jsonb,'شبكات كشف البرق والتحليل التشغيلي'),
('operational-lightning-information','إنتاج معلومات البرق التشغيلية','الخرائط والتنبيهات والمنتجات التفسيرية','{"blocks":[{"type":"heading","text":"المفهوم العلمي"},{"type":"text","text":"تحول مراكز الأرصاد بيانات البرق إلى خرائط كثافة ونشاط زمني وملخصات عواصف، مع توثيق التغطية والدقة وحدود الكشف. ينبغي أن تكون الرسائل واضحة ومتكاملة مع منتجات الطقس الأخرى."},{"type":"heading","text":"الأساس الفيزيائي"},{"type":"text","text":"تنتج الظواهر الكهربائية الجوية من حركة الشحنات وفصلها وانتقالها ضمن وسط غازي متغير الموصلية. ويتطلب تفسيرها الجمع بين القياس الكهربائي والظروف الميكروفيزيائية والديناميكية والبيئية، مع التمييز بين الإشارة المقاسة والاستنتاج الفيزيائي."},{"type":"heading","text":"البيانات والأجهزة"},{"type":"list","items":["المجال الكهربائي والجهد والتيار أو الموصلية بحسب الجهاز.","إشارات المستشعرات الكهرومغناطيسية أو البصرية وتوقيتها.","بيانات الرادار والأقمار الصناعية والطقس السطحي.","موقع المحطات وهندستها ومعايرتها وحالة الاتصال.","سجلات الأحداث الخام وبيانات ضبط الجودة."]},{"type":"heading","text":"منهجية التحليل"},{"type":"list","items":["حدد الظاهرة ونوع الإشارة التي يقيسها الجهاز مباشرة.","تحقق من التوقيت والمعايرة وحدود الكشف.","اربط الإشارة بالبنية السحابية والبيئة الجوية.","ادمج مصادر الرصد مع توحيد الإسقاط والزمن.","اعرض عدم اليقين والتغطية ومعدل الأحداث غير المكتشفة."]},{"type":"heading","text":"مثال تطبيقي"},{"type":"example","title":"إنتاج معلومات البرق التشغيلية","text":"اقترح مجموعة منتجات يومية وأرشيفية لشبكة وطنية لكشف البرق. استخدم حالة افتراضية تعليمية، وبيّن ما يمكن استنتاجه وما يحتاج إلى قياسات إضافية."},{"type":"heading","text":"المهمة العملية"},{"type":"text","text":"اقترح مجموعة منتجات يومية وأرشيفية لشبكة وطنية لكشف البرق."},{"type":"heading","text":"أخطاء شائعة"},{"type":"list","items":["اعتبار كل إشارة كهربائية حدث برق مؤكداً.","إهمال كفاءة الكشف وتغيرها مع الزمن.","الخلط بين كثافة الأحداث ومستوى الخطر المحلي.","دمج مصادر غير متزامنة دون توثيق الفروق الزمنية.","إسناد اتجاه مناخي قبل فحص تجانس شبكة الرصد."]},{"type":"callout","text":"تفسير البرق والكهرباء الجوية يتطلب شبكة رصد معايرة وسياقاً جوياً متكاملاً، لا مجرد عرض نقاط على الخريطة."},{"type":"heading","text":"الخلاصة"},{"type":"text","text":"يوفر الرصد الكهربائي بعداً إضافياً لفهم العواصف والهباء والغلاف الجوي. وتنبع القيمة التشغيلية من تكامل المستشعرات وضبط الجودة والتفسير متعدد المصادر."}]}'::jsonb,8750,55,'["شرح الآلية الكهربائية الجوية أو مبدأ الرصد المرتبط بالموضوع","تحليل بيانات المستشعرات وربطها بالسياق الجوي","تقييم جودة الشبكة ومصادر عدم اليقين في المنتجات"]'::jsonb,'شبكات كشف البرق والتحليل التشغيلي')
)
insert into public.academy_lessons(course_id,chapter_id,unit_id,chapter_title,unit_title,slug,title,summary,content,published,sort_order,estimated_minutes,learning_objectives,level)
select c.id,ch.id,case when d.unit_title='الكهرباء الجوية وتكهرب السحب' then u1.id else u2.id end,'الكهرباء الجوية والبرق ورصد العواصف',d.unit_title,d.slug,d.title,d.summary,d.content,false,d.ord,d.mins,d.objectives,'advanced'
from d cross join c cross join ch cross join u1 cross join u2
on conflict(course_id,slug) do update set chapter_id=excluded.chapter_id,unit_id=excluded.unit_id,chapter_title=excluded.chapter_title,unit_title=excluded.unit_title,title=excluded.title,summary=excluded.summary,content=excluded.content,published=false,sort_order=excluded.sort_order,estimated_minutes=excluded.estimated_minutes,learning_objectives=excluded.learning_objectives,level=excluded.level;